-- Weapon categories (Gabriel locked 2026-10-16). Idempotent. Maps the 8 categories onto the existing weapons table
-- and class_item_proficiencies (match_field='weapon_category', match_value=code). Removes simple/martial and focus text.
BEGIN;
CREATE TABLE IF NOT EXISTS weapon_category (id INT PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, definition TEXT);
INSERT INTO weapon_category (id,code,name,definition) VALUES
(1,'MIN','Minor','Daggers, small weapons, fist weapons and the quarterstaff. Every class has them.'),
(2,'EL1','Elegant One-Handed','One-handed DEX (finesse) melee weapons.'),
(3,'BR1','Broad One-Handed','One-handed STR melee weapons that aren''t versatile.'),
(4,'RG1','Ranged One-Handed','Weapons thrown or shot with one hand.'),
(5,'VER','Versatile','Melee weapons used in one or two hands.'),
(6,'RCH','Reach','Two-handed weapons with reach.'),
(7,'GRT','Great','Two-handed STR weapons without reach.'),
(8,'RG2','Ranged Two-Handed','Bows and crossbows that need two hands.')
ON CONFLICT (id) DO UPDATE SET code=EXCLUDED.code,name=EXCLUDED.name,definition=EXCLUDED.definition;
ALTER TABLE weapons ADD COLUMN IF NOT EXISTS category_id INT REFERENCES weapon_category(id);
ALTER TABLE weapons ADD COLUMN IF NOT EXISTS family_tag TEXT;
ALTER TABLE weapons DROP COLUMN IF EXISTS weapon_type;
INSERT INTO weapons (name,category,damage_dice,damage_type,properties,range_normal,range_long,versatile_dice,description,rarity)
