('Sling','Ranged One-Handed weapon: 1d4 bludgeoning. Properties: ammunition (30/120).'),
('Net','Ranged One-Handed weapon: no damage. Properties: special, thrown (5/15).'),
('Trident','Versatile weapon: 1d6 piercing. Properties: thrown (20/60), versatile (1d8).'),
('Soul Brand','Versatile weapon: 1d8 bludgeoning or slashing. Properties: versatile (1d10), thrown (20/60, returns from L2). Summoned by the Soul Smith feature; uses CHA for attack and damage.'),
('Pike','Reach weapon: 1d10 piercing. Properties: heavy, reach, two-handed.'),
('Halberd','Reach weapon: 1d10 slashing. Properties: heavy, reach, two-handed.'),
('Lance','Reach weapon: 1d12 piercing. Properties: reach, special (disadvantage within 5 ft; two-handed unless mounted). Cavalier mounted rules apply.'),
('Greatclub','Great weapon: 1d8 bludgeoning. Properties: two-handed.'),
('Maul','Great weapon: 2d6 bludgeoning. Properties: heavy, two-handed.'),
('War Flail','Great weapon: 1d10 bludgeoning. Properties: heavy, two-handed.'),
('Heavy Crossbow','Ranged Two-Handed weapon: 1d10 piercing. Properties: ammunition (100/400), heavy, loading, two-handed.')
) v(n,d) WHERE w.name=v.n;
ALTER TABLE weapons DROP CONSTRAINT IF EXISTS weapons_rarity_check;
ALTER TABLE weapons ALTER COLUMN rarity SET DEFAULT 'Common';
UPDATE weapons SET rarity = CASE lower(coalesce(rarity,'common')) WHEN 'common' THEN 'Common' WHEN 'uncommon' THEN 'Uncommon' WHEN 'rare' THEN 'Rare' WHEN 'very rare' THEN 'Very Rare' WHEN 'legendary' THEN 'Legendary' WHEN 'mythical' THEN 'Artifact' WHEN 'artifact' THEN 'Artifact' END;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM weapons WHERE rarity IS NULL OR description IS NULL) THEN RAISE EXCEPTION 'weapon missing rarity/description'; END IF; END $$;
ALTER TABLE weapons ADD CONSTRAINT weapons_rarity_check CHECK (rarity IN ('Common','Uncommon','Rare','Very Rare','Legendary','Artifact'));
DELETE FROM class_item_proficiencies WHERE item_kind='weapon';
ALTER TABLE class_item_proficiencies DROP CONSTRAINT IF EXISTS class_item_proficiencies_match_field_check;
ALTER TABLE class_item_proficiencies ADD CONSTRAINT class_item_proficiencies_match_field_check CHECK (match_field IN ('armor_type','weapon_category'));
-- Dual wield toggle (Actions tab), saved per character and owned weapon
ALTER TABLE character_weapons ADD COLUMN IF NOT EXISTS dual_wield BOOLEAN NOT NULL DEFAULT false;
