UPDATE classes c SET weapon_proficiencies = (SELECT string_agg(wc.name, ', ' ORDER BY wc.id) FROM class_item_proficiencies p JOIN weapon_category wc ON wc.code=p.match_value
  WHERE p.class_id=c.id AND p.subclass_id IS NULL AND p.item_kind='weapon') || CASE WHEN c.name='Soul Smith' THEN ', Oversized (any size)' ELSE '' END;
UPDATE sub_classes s SET weapon_proficiencies = (SELECT string_agg(wc.name, ', ' ORDER BY wc.id) FROM class_item_proficiencies p JOIN weapon_category wc ON wc.code=p.match_value
  WHERE p.subclass_id=s.id AND p.item_kind='weapon');
UPDATE class_features SET description=replace(description,' Your ritual blade can be your focus.','') WHERE name='Witchcraft' AND position(' Your ritual blade can be your focus.' in description)>0;
UPDATE subclass_features SET description=replace(description,'Bond two weapons; both count as your focus.','Bond two weapons.') WHERE name='Hexblade Ascendant' AND position('Bond two weapons; both count as your focus.' in description)>0;
UPDATE subclass_features SET description=replace(description,'Gain medium armor and martial melee weapon proficiency.','Gain medium armor and proficiency with the Elegant One-Handed, Broad One-Handed and Versatile weapon categories.') WHERE name='Witch Knight Training' AND position('Gain medium armor and martial melee weapon proficiency.' in description)>0;
UPDATE subclass_features SET description=replace(description,', and it''s your spellcasting focus.','.') WHERE name='Runed Weapon and Runic Strike' AND position(', and it''s your spellcasting focus.' in description)>0;
UPDATE subclass_features SET description=replace(description,'light armor and martial blades (shortsword, longsword, scimitar, rapier)','light armor and the Elegant One-Handed and Versatile weapon categories') WHERE name='Inscribe Arms' AND position('light armor and martial blades (shortsword, longsword, scimitar, rapier)' in description)>0;
UPDATE class_features SET description=replace(description,', using an instrument as your focus.','.') WHERE name='Spellcasting' AND position(', using an instrument as your focus.' in description)>0;
UPDATE subclass_features SET description=replace(description,'Gain medium armor and martial weapon proficiency.','Gain medium armor and proficiency with the Broad One-Handed, Versatile and Ranged Two-Handed weapon categories.') WHERE name='Battle Chorus' AND position('Gain medium armor and martial weapon proficiency.' in description)>0;
UPDATE class_features SET description=replace(description,'(1d8 slashing, finesse, one-handed, not light). It counts as a focus for Gracewraith features, but not for another class''s spells.','(an Elegant One-Handed weapon: 1d8 slashing, finesse, one-handed, not light).') WHERE name='Sigil Blade' AND position('(1d8 slashing, finesse, one-handed, not light). It counts as a focus for Gracewraith features, but not for another class''s spells.' in description)>0;
UPDATE class_features SET description=replace(description,' A sigil blade is a spellcasting focus for Gracewraith spells only.','') WHERE name='Spellcasting' AND position(' A sigil blade is a spellcasting focus for Gracewraith spells only.' in description)>0;
UPDATE class_features SET description=replace(description,'Your chains and flails','Your chain whips and flails') WHERE name='Chain Reach' AND position('Your chains and flails' in description)>0;
UPDATE class_features SET description=replace(description,'sigil blade, chain, or flail','sigil blade, chain whip, or flail') WHERE name='Sigil Strike' AND position('sigil blade, chain, or flail' in description)>0;
UPDATE class_features SET description=replace(description,'sigil blade, chain, and flail hits','sigil blade, chain whip, and flail hits') WHERE name='Stolen Radiance' AND position('sigil blade, chain, and flail hits' in description)>0;
UPDATE class_features SET description=replace(description,'Martial melee; use CHA','Versatile category; use CHA') WHERE name='Soul Brand' AND position('Martial melee; use CHA' in description)>0;
UPDATE class_features SET description=replace(description,' Counts as a focus for Soul Smith features.','') WHERE name='Soul Brand' AND position(' Counts as a focus for Soul Smith features.' in description)>0;
UPDATE subclass_features SET description=replace(description,'; soul brand is your focus;',';') WHERE name='Possession Spellcasting' AND position('; soul brand is your focus;' in description)>0;
UPDATE class_features SET description=replace(description,', and use an arcane focus or your staff as a focus.','.') WHERE name='Arcane Initiate' AND position(', and use an arcane focus or your staff as a focus.' in description)>0;
UPDATE spells SET base_description=replace(base_description,'S, M (a little makeup);','S;') WHERE name='Friends';
UPDATE primordial_blessings SET name='Paired Edge' WHERE name='Twin Fangs';
UPDATE class_features SET options=array_replace(options,'Twin Fangs','Paired Edge') WHERE 'Twin Fangs'=ANY(options);
UPDATE subclass_features SET options=array_replace(options,'Twin Fangs','Paired Edge') WHERE 'Twin Fangs'=ANY(options);
UPDATE characters SET feature_choices=replace(feature_choices::text,'"Twin Fangs"','"Paired Edge"')::jsonb WHERE feature_choices::text LIKE '%"Twin Fangs"%';
COMMIT;
